<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { composeEventHandlers } from '../shared/events.js'; import { getMenuContext, getMenuRadioGroupContext, MenuRadioItemState, setMenuRadioItemContext, type MenuItemRecord } from './menu-context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; value: string; disabled?: boolean; textValue?: string; ref?: HTMLDivElement | null; } let { children, value, disabled = false, textValue = '', ref = $bindable(null), onclick, ...rest }: Props = $props(); const menu = getMenuContext(); const group = getMenuRadioGroupContext(); const itemState = setMenuRadioItemContext(new MenuRadioItemState()); let checked = $derived(group.value === value); $effect.pre(() => { itemState.checked = checked; }); $effect(() => { if (!ref) return; const item: MenuItemRecord = { element: ref, disabled, text: textValue || ref.textContent?.trim() || '' }; return menu.register(item); });</script>
<div bind:this={ref} {...rest} role="menuitemradio" tabindex="-1" aria-checked={checked} aria-disabled={disabled || undefined} data-checked={checked ? '' : undefined} data-disabled={disabled ? '' : undefined} onclick={composeEventHandlers(onclick, (event) => { if (!disabled) group.select(value, event); })}>{@render children?.()}</div>
